752						}}, nil
753					},
754					func(seq int) (string, *PolicyChange, *DecisionRecord) {
755						return AuditDecision, nil, &DecisionRecord{Request: req, Decision: claim}
756					},
757				})
758				got, err := RecheckDecisionOffline(org, recs, cp, 2)
